function homeCtrl(e,t,o){e.init=()=>{t.getData("get","/Home/ReadGestionCantidad").then((function(t){0!=t.id?e.cantidad=t.data:toast.toastr("warning",t.message,t.titleSms)}))},e.init(),e.docs=[],e.fixDocs=()=>{location.href="/DocumentoElectronico/Index?tipo=3"};var n=new Date;if(n.getHours()<17)var a=60*(17-n.getHours())*60*1e3;else{var i=new Date(n.getTime()+864e5);i.setHours(17),i.setMinutes(0),i.setSeconds(0);a=i.getTime()-n.getTime();o(function(){try{t.getData("GET","DocumentoElectronico?json="+JSON.stringify({tipo:3}),null,!0).then((t=>{"1"==t.code&&(e.docs=JSON.parse(t.payload)[0],$("#comprobantesErroneosModal").modal("show"))})).catch((e=>{}))}catch(e){}}(),a)}}app.controller("homeCtrl",homeCtrl),homeCtrl.$inject=["$scope","mainService","$interval"];